import { useEffect } from "react";
import { useParams, useNavigate, Link } from "react-router-dom";
import { useGames } from "../hooks/useGames";
import { CATEGORY_META } from "../utils/gameUtils";

function updateMetaTag(name, content, property = false) {
  if (!content) return;
  const selector = property ? `meta[property="${name}"]` : `meta[name="${name}"]`;
  let element = document.head.querySelector(selector);
  if (!element) {
    element = document.createElement("meta");
    if (property) {
      element.setAttribute("property", name);
    } else {
      element.setAttribute("name", name);
    }
    document.head.appendChild(element);
  }
  element.setAttribute("content", content);
}

export default function GamePage() {
  const { id } = useParams();
  const nav = useNavigate();
  const { games, loading } = useGames();

  if (loading) return <h2 className="loading-text">Loading Game...</h2>;

  const game = games.find((g) => g.slug === id || g._id === id || g.Name.toLowerCase().replace(/[^a-z0-9]+/g, "-") === id);

  useEffect(() => {
    if (!game) return;

    document.title = `${game.Name} • PokiPlay`;
    updateMetaTag("description", game.description);
    updateMetaTag("og:title", `${game.Name} • PokiPlay`, true);
    updateMetaTag("og:description", game.description, true);
    updateMetaTag("og:type", "website", true);
  }, [game]);

  if (!game) {
    return (
      <div className="not-found">
        <h2>Game Not Found</h2>
        <button className="btn-primary" onClick={() => nav("/")}>Back to Home</button>
      </div>
    );
  }

  const categoryMeta = CATEGORY_META[game.category] || CATEGORY_META.Other;
  const relatedGames = game.relatedSlugs
    .map((slug) => games.find((other) => other.slug === slug))
    .filter(Boolean);

  const relatedFallback = relatedGames.length
    ? relatedGames
    : games.filter((other) => other.category === game.category && other.slug !== game.slug).slice(0, 6);

  return (
    <div className="game-container">
      <div className="game-header">
        <button className="btn-back" onClick={() => nav("/")}>⬅ Back</button>
        <div>
          <h2>{game.Name}</h2>
          <div className="game-meta-row">
            <span className="category-badge" style={{ background: `${categoryMeta.color}22`, color: categoryMeta.color }}>
              {categoryMeta.icon} {game.category}
            </span>
            {game.isTrending && <span className="status-badge trending">Trending</span>}
            {game.isNew && <span className="status-badge new">New</span>}
          </div>
        </div>
      </div>

      <div className="game-details-grid">
        <div className="game-summary-card">
          <h3>About this game</h3>
          <p>{game.description}</p>
          <h4>Instructions</h4>
          <p>{game.instructions}</p>
          <div className="game-links-row">
            <Link to="/search" className="btn-primary">Browse More Games</Link>
            <button className="btn-back" onClick={() => nav(-1)}>Go Back</button>
          </div>
        </div>
        <div className="iframe-wrapper game-page-iframe">
          <iframe
            src={game.Link}
            title={game.Name}
            allowFullScreen
            className="game-iframe"
          />
        </div>
      </div>

      <div className="related-section">
        <div className="category-header">
          <div>
            <span className="category-label" style={{ background: `${categoryMeta.color}22`, color: categoryMeta.color }}>
              {categoryMeta.icon}
            </span>
            <span className="category-count">Related games</span>
          </div>
        </div>
        <div className="related-carousel">
          {relatedFallback.map((related) => (
            <div key={related._id} className="related-card">
              <Link to={`/game/${related.slug}`} className="card-link">
                <img src={related.Icon} alt={related.Name} loading="lazy" />
                <div className="related-body">
                  <p>{related.Name}</p>
                </div>
              </Link>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
